#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    map<long long, long long> frequency;
    for (long long i = 0, value; i < m; ++i) {
        cin >> value;
        ++frequency[value];
    }

    if (n <= 0 || m < n) {
        cout << 0 << '\n';
        return 0;
    }

    long long low = 1, high = m / n, answer = 0;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long count = 0;

        for (const auto& [value, freq] : frequency) {
            count += freq / mid;
            if (count >= n) break;
        }

        if (count >= n) {
            answer = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    cout << answer << '\n';
    return 0;
}

